SELECT p.oid::regprocedure::text AS signature,p.proowner::regrole::text AS owner,p.prosecdef AS security_definer,p.proconfig AS config,pg_get_functiondef(p.oid) AS definition FROM pg_proc p WHERE p.oid IN (SELECT t.tgfoid FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='storage' AND NOT t.tgisinternal) ORDER BY signature;
